import React, { useState, useEffect } from 'react';
import { Search, ChevronLeft, ChevronRight, Heart, X, SlidersHorizontal } from 'lucide-react';

const ProductCard = ({ product, onToggleSave, isSaved }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxImageIndex, setLightboxImageIndex] = useState(0);
  const [showDetailsModal, setShowDetailsModal] = useState(false);

  const images = product.images || [];
  const hasMultipleImages = images.length > 1;

  const minSwipeDistance = 50;

  const onTouchStart = (e) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;
    if (isLeftSwipe) nextImage();
    if (isRightSwipe) prevImage();
  };

  const getConditionStyle = (condition) => {
    const normalizedCondition = condition?.trim();
    const styles = {
      'Brand New': { bgColor: '#0284C7', textColor: '#FFFFFF', hasShimmer: true },
      'Excellent': { bgColor: '#16A34A', textColor: '#FFFFFF', hasShimmer: false },
      'Like New': { bgColor: '#16A34A', textColor: '#FFFFFF', hasShimmer: false },
      'Very Good': { bgColor: '#0D9488', textColor: '#FFFFFF', hasShimmer: false },
      'Good': { bgColor: '#F59E0B', textColor: '#1F2937', hasShimmer: false },
      'Fair': { bgColor: '#F97316', textColor: '#1F2937', hasShimmer: false },
      'Poor': { bgColor: '#DC2626', textColor: '#FFFFFF', hasShimmer: false },
    };
    return styles[normalizedCondition] || { bgColor: '#0D9488', textColor: '#FFFFFF', hasShimmer: false };
  };

  const conditionStyle = getConditionStyle(product.condition);

  const nextImage = (e) => {
    if (e) e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e) => {
    if (e) e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const openLightbox = (index) => {
    setLightboxImageIndex(index);
    setIsLightboxOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setIsLightboxOpen(false);
    document.body.style.overflow = 'auto';
  };

  const nextLightboxImage = (e) => {
    e.stopPropagation();
    setLightboxImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevLightboxImage = (e) => {
    e.stopPropagation();
    setLightboxImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  return (
    <>
      <div className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-xl transition-all duration-300 flex flex-col h-full">
        <div 
          className="relative bg-gray-100 overflow-hidden group rounded-t-lg cursor-pointer" 
          style={{ paddingBottom: '100%' }}
          onTouchStart={onTouchStart}
          onTouchMove={onTouchMove}
          onTouchEnd={onTouchEnd}
          onClick={() => openLightbox(currentImageIndex)}
        >
          <div 
            className="absolute inset-0 flex transition-transform duration-500 ease-out" 
            style={{ transform: `translateX(-${currentImageIndex * 100}%)` }}
          >
            {images.map((img, idx) => (
              <img
                key={idx}
                src={img}
                alt={`${product.name} - Image ${idx + 1}`}
                className="w-full h-full object-cover flex-shrink-0"
              />
            ))}
          </div>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onToggleSave(product.id);
            }}
            className="absolute top-3 right-3 hover:scale-110 transition-all duration-200 z-10"
          >
            <Heart
              size={26}
              strokeWidth={2}
              className={isSaved ? 'fill-red-500 text-red-500' : 'text-white drop-shadow-lg'}
            />
          </button>

          {hasMultipleImages && (
            <>
              <button
                onClick={prevImage}
                className="absolute left-3 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 hover:scale-110 z-10"
              >
                <ChevronLeft className="text-white drop-shadow-lg" size={32} strokeWidth={2.5} />
              </button>

              <button
                onClick={nextImage}
                className="absolute right-3 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 hover:scale-110 z-10"
              >
                <ChevronRight className="text-white drop-shadow-lg" size={32} strokeWidth={2.5} />
              </button>

              <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex space-x-1.5">
                {images.map((_, index) => (
                  <button
                    key={index}
                    onClick={(e) => {
                      e.stopPropagation();
                      setCurrentImageIndex(index);
                    }}
                    className={`h-1.5 rounded-full transition-all duration-200 ${
                      index === currentImageIndex ? 'bg-gray-800 w-4' : 'bg-gray-400 w-1.5'
                    }`}
                  />
                ))}
              </div>
            </>
          )}
        </div>

        <div className="p-4 flex flex-col h-full" style={{ minHeight: '280px' }}>
          <h3 className="text-base font-semibold text-gray-900 mb-2">{product.name}</h3>

          <div className="mb-2">
            {conditionStyle.hasShimmer ? (
              <span 
                className="relative px-3 py-1 rounded-md text-xs font-normal uppercase overflow-hidden inline-block"
                style={{ 
                  backgroundColor: conditionStyle.bgColor, 
                  color: conditionStyle.textColor 
                }}
              >
                <span className="relative z-10">{product.condition}</span>
                <span 
                  className="absolute inset-0 -translate-x-full animate-shimmer bg-gradient-to-r from-transparent via-white/30 to-transparent"
                  style={{ animationDuration: '2s', animationIterationCount: 'infinite' }}
                ></span>
              </span>
            ) : (
              <span 
                className="px-3 py-1 rounded-md text-xs font-normal uppercase"
                style={{ 
                  backgroundColor: conditionStyle.bgColor, 
                  color: conditionStyle.textColor 
                }}
              >
                {product.condition}
              </span>
            )}
          </div>

          <div className="flex items-center gap-2 mb-2 flex-wrap">
            {product.year && (
              <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal">
                {product.year}
              </span>
            )}
            {product.screenSize && (
              <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal">
                {product.screenSize}
              </span>
            )}
            {product.ram && (
              <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal">
                {product.ram}
              </span>
            )}
            {product.memory && (
              <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal">
                {product.memory}
              </span>
            )}
            {product.boxCharger && product.boxCharger.toLowerCase() === 'yes' && (
              <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal">
                Box & Charger
              </span>
            )}
          </div>

          <div className="mb-2 flex-grow">
  <p className="text-sm text-gray-600 leading-relaxed line-clamp-3">
    {product.description}
  </p>
  <button 
    onClick={(e) => {
      e.stopPropagation();
      setShowDetailsModal(true);
    }}
    className="text-sm text-gray-600 hover:underline font-semibold mt-1"
  >
    Read more
  </button>
</div>

          <div className="flex items-center justify-between mt-auto">
            <div>
              <p className="text-xs text-gray-500 uppercase mb-0.5">Price</p>
              <p className="text-lg font-bold text-gray-900">${product.price.toFixed(2)}</p>
            </div>
            <button className="bg-gray-900 text-white px-6 py-2.5 rounded-md text-sm font-semibold hover:bg-gray-800 transition-colors duration-200">
              Buy Now
            </button>
          </div>
        </div>
      </div>

      {isLightboxOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-95 z-50 flex items-center justify-center p-4"
          onClick={closeLightbox}
        >
          <button
            onClick={closeLightbox}
            className="absolute top-4 right-4 text-white hover:scale-110 transition-transform duration-200 z-50"
          >
            <X size={40} strokeWidth={2} />
          </button>

          <div className="relative max-w-6xl max-h-full w-full h-full flex items-center justify-center" onClick={(e) => e.stopPropagation()}>
            <img
              src={images[lightboxImageIndex]}
              alt={`${product.name} - Image ${lightboxImageIndex + 1}`}
              className="max-w-full max-h-full object-contain"
            />

            {hasMultipleImages && (
              <>
                <button
                  onClick={prevLightboxImage}
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-white hover:scale-110 transition-transform duration-200"
                >
                  <ChevronLeft size={48} strokeWidth={2.5} className="drop-shadow-lg" />
                </button>

                <button
                  onClick={nextLightboxImage}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-white hover:scale-110 transition-transform duration-200"
                >
                  <ChevronRight size={48} strokeWidth={2.5} className="drop-shadow-lg" />
                </button>

                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black bg-opacity-60 text-white px-4 py-2 rounded-full text-sm">
                  {lightboxImageIndex + 1} / {images.length}
                </div>
              </>
            )}
          </div>

          <div className="absolute bottom-4 left-4 bg-black bg-opacity-60 text-white px-4 py-2 rounded-lg max-w-md">
            <h3 className="font-semibold">{product.name}</h3>
            <p className="text-sm">${product.price.toFixed(2)}</p>
          </div>
        </div>
      )}
      {showDetailsModal && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4"
          onClick={() => setShowDetailsModal(false)}
        >
          <div 
            className="bg-white rounded-lg max-w-2xl max-h-[80vh] overflow-y-auto p-6 relative"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => setShowDetailsModal(false)}
              className="absolute top-4 right-4 text-gray-500 hover:text-gray-700"
            >
              <X size={24} />
            </button>

            <h2 className="text-2xl font-bold text-gray-900 mb-4 pr-8">{product.name}</h2>

            <div className="space-y-4">
              <div>
                <h3 className="font-semibold text-gray-700 mb-2">Description</h3>
                <p className="text-gray-600 leading-relaxed">{product.description}</p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <h3 className="font-semibold text-gray-700 mb-2">Specifications</h3>
                  <div className="space-y-2 text-sm">
                    {product.condition && (
                      <p><span className="font-medium">Condition:</span> {product.condition}</p>
                    )}
                    {product.year && (
                      <p><span className="font-medium">Year:</span> {product.year}</p>
                    )}
                    {product.screenSize && (
                      <p><span className="font-medium">Screen Size:</span> {product.screenSize}</p>
                    )}
                    {product.ram && (
                      <p><span className="font-medium">RAM:</span> {product.ram}</p>
                    )}
                    {product.memory && (
                      <p><span className="font-medium">Memory:</span> {product.memory}</p>
                    )}
                    {product.boxCharger && (
                      <p><span className="font-medium">Box & Charger:</span> {product.boxCharger}</p>
                    )}
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold text-gray-700 mb-2">Price</h3>
                  <p className="text-3xl font-bold text-gray-900">${product.price.toFixed(2)}</p>
                  <button className="mt-4 w-full bg-gray-900 text-white px-6 py-3 rounded-md font-semibold hover:bg-gray-800 transition-colors duration-200">
                    Buy Now
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

